    public final Map<String,Integer> WordsToCounts=new HashMap<>();
    private static boolean Letter(char value){return value>='A'&&value<='Z'||value>='a'&&value<='z';}
    public WordCloudData(String text){
        int index=0;
        while(index<text.length()){
            if(!Letter(text.charAt(index))){index++;continue;}
            int start=index++;
            while(index<text.length()){
                char current=text.charAt(index);
                if(Letter(current)){index++;continue;}
                if((current=='\''||current=='-')&&index+1<text.length()&&Letter(text.charAt(index+1))){index+=2;continue;}
                break;
            }
            String word=text.substring(start,index).toLowerCase(Locale.ROOT);
            WordsToCounts.put(word,WordsToCounts.getOrDefault(word,0)+1);
        }
    }
}

